"use client";

import { motion } from "framer-motion";
import { Check, ArrowRight, Clock, Target } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ButtonLink } from "@/components/ui/button-link";
import { cn } from "@/lib/utils";

interface PricingExample {
  type: string;
  price: string;
}

interface PricingCardProps {
  name: string;
  description: string;
  price: string;
  bullets: string[];
  featured?: boolean;
  ctaLabel?: string;
  ctaHref?: string;
  className?: string;
  // New props
  duration?: string;
  idealFor?: string;
  badge?: string;
  examples?: PricingExample[];
  useCases?: string[];
  comparison?: {
    vsFreelance?: string[];
    vsRecrutement?: string[];
  };
}

export function PricingCard({
  name,
  description,
  price,
  bullets,
  featured = false,
  ctaLabel = "Commencer",
  ctaHref = "/contact",
  className,
  duration,
  idealFor,
  badge,
  examples,
  useCases,
  comparison,
}: PricingCardProps) {
  return (
    <motion.div
      whileHover={{ y: -4 }}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
    >
      <Card
        variant={featured ? "elevated" : "default"}
        className={cn(
          "relative flex h-full flex-col p-6 md:p-8",
          featured && "border-primary/30 shadow-glow",
          className
        )}
      >
        {/* Featured badge */}
        {featured && (
          <div className="absolute -top-3 left-1/2 -translate-x-1/2">
            <Badge className="bg-primary text-white shadow-md">
              Populaire
            </Badge>
          </div>
        )}

        {/* Custom badge (like "Nouveau") */}
        {badge && !featured && (
          <div className="absolute -top-3 left-1/2 -translate-x-1/2">
            <Badge variant="secondary" className="shadow-md">
              {badge}
            </Badge>
          </div>
